const upper = (str) => {
  if (!str) return ''
  return str.charAt(0).toUpperCase() + str.slice(1)
}

const pascal = (str) => {
  return (str || '')
    .replace(/[{}]/g, '')
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map(upper)
    .join('')
}

const normalizeNamePath = (path) => {
  return (path || '')
    .replace(/\$\{(?:pathParams\.)?(\w+)\}/g, '{$1}')
}

const normalizeRuntimePath = (path) => {
  return (path || '')
    .replace(/(^|[^$])\{(\w+)\}/g, '$1${$2}')
}

const buildResolvedFunctionName = () => {
  const method = (options.apiMethod || 'get').toLowerCase()
  const pathParams = options.pathParams || []

  if (pathParams.length <= 1) {
    return options.apiFunctionName
  }

  const normalizedPath = normalizeNamePath(options.apiPath || '')
  const staticSegments = normalizedPath
    .split('/')
    .filter(Boolean)
    .filter((segment) => !/^\{.+\}$/.test(segment))
    .filter((segment) => !['admin', 'compendiums'].includes(segment))

  return `${method}${staticSegments.map(pascal).join('')}`
}

function fun() {
  const args = []

  const buildParams = () => {
    if (options.pathParams.length) {
      if (options.pathParams.length > 1) {
        args.push(`pathParams: Expand<${options.pathParamsType}>`)
      } else {
        args.push(`${options.pathParams[0].name}: ${options.buildParameters(options.pathParams[0])}`)
      }
    }

    if (options.queryParams.length) {
      args.push(`params: Expand<${options.queryParamsType}>`)
    }

    if (!['get', 'delete', 'head', 'options'].includes(options.apiMethod || 'get') && options.haveReqBody) {
      args.push(`data: Expand<${options.dataParamsType}>`)
    }

    args.push('config?: Expand<ParticalUniAppRequestOptions>')
  }

  buildParams()

  const path = normalizeRuntimePath(options.apiPath || '')
  const url = `\`${path}\``

  let bodyParams = ''
  if (['get', 'delete', 'head', 'options'].includes(options.apiMethod || 'get')) {
    bodyParams = options.queryParams.length ? 'params, ' : '{}, '
  } else {
    bodyParams = options.haveReqBody ? 'data, ' : '{}, '
  }

  const resolvedFunctionName = buildResolvedFunctionName()

  return `export const ${resolvedFunctionName} = async (${args.join(', ')}): Promise<Expand<${options.apiFunctionName}Res>> => {\n    const _config = baseURL ? { baseURL, ...config } : config\n    return http.${options.apiMethod}(${url}, ${bodyParams}_config)\n}`
}

fun()

