const generateFunction = () => {
  const resolvedFunctionName = buildResolvedFunctionName()
  const resolvedExtraFunctionName = `use${upper(resolvedFunctionName)}`
  const requestPath = normalizeRuntimePath(options.apiPath || '')

  let args = []

  const buildParams = () => {
    if (options.pathParams.length) {
      if (options.pathParams.length > 1) {
        args.push(`pathParams: Expand<${options.pathParamsType}>`)
      } else {
        args.push(`${options.pathParams[0].name}: string`)
      }
    }

    if (options.queryParams.length) {
      args.push(`params: Expand<${options.queryParamsType}>`)
    }

    args.push('fetchOptions: Expand<RequestInit> = {}')
    args.push('_queryOptions?: object = {}')

    return args.join(', ')
  }

  const _buildParams = buildParams()

  if (['get', 'delete'].includes(options.apiMethod)) {
    const haveQueryParams = options.queryParams.length > 0
    const allPath = haveQueryParams
      ? `[\`${requestPath}\`, params, fetchOptions]`
      : `[\`${requestPath}\`, fetchOptions]`

    const queryFnArgs =
      options.pathParams.length > 1
        ? `pathParams, ${haveQueryParams ? 'params, ' : ''}fetchOptions`
        : `${options.pathParams.length ? `${options.pathParams[0].name}, ` : ''}${haveQueryParams ? 'params, ' : ''}fetchOptions`

    const a = `\nexport const ${resolvedExtraFunctionName} = (${_buildParams}) => {\n    return useQuery({queryKey: ${allPath}, queryFn: () => ${resolvedFunctionName}(${queryFnArgs}), ..._queryOptions})\n}`
    const b = `\nexport const useOption${upper(resolvedFunctionName)} = (${_buildParams}) => {\n    return queryOptions({queryKey: ${allPath}, queryFn: () => ${resolvedFunctionName}(${queryFnArgs}), ..._queryOptions})\n}`

    return a + b
  }

  return `\nexport const ${resolvedExtraFunctionName} = (_queryOptions?: object = {}) => {\n   return useMutation({mutationFn: ${resolvedFunctionName}, ..._queryOptions})\n}`
}

generateFunction()
